function changeLabel(kind){const key=String(kind?.type||kind||'').toLowerCase();return key.includes('add')||key==='create'?tr('added'):key.includes('delete')||key.includes('remove')?tr('deleted'):tr('modified')}
function setStreamText(id,kind,text){if(id)state.streamText.set(`${id}:${kind}`,String(text||''))}
function getStreamText(id,kind,fallback=''){return state.streamText.get(`${id}:${kind}`)??String(fallback||'')}
function userImageUrl(value){const url=String(value||'');return /^(data:image\/(?:png|jpe?g|webp|gif|bmp);|blob:|https?:\/\/)/i.test(url)?url:''}
function userContent(item){const content=Array.isArray(item?.content)?item.content:[];const text=[];const images=[];for(const value of content){if(typeof value==='string'){text.push(value);continue}const type=String(value?.type||'').toLowerCase();const url=userImageUrl(value?.image_url||value?.url);if(url&&(type==='input_image'||type==='image')){images.push(url);continue}const part=value?.text||value?.input_text||value?.output_text;if(part)text.push(part);else if(value?.path&&type!=='localimage')text.push(value.path)}return{text:text.join('\n')||item?.text||'',images}}
function renderUser(item){const n=el('div','message user item');n.dataset.itemId=itemKey(item);const content=userContent(item),bubble=el('div','message-bubble');if(content.text)bubble.append(el('div','message-text',content.text));for(const url of content.images){const image=document.createElement('img');image.className='message-image';image.src=url;image.alt=tr('attachImage');bubble.append(image)}if(!content.text&&!content.images.length)bubble.textContent='';n.append(el('div','message-label',tr('user')),bubble);return n}
