function renderWebSearch(item){const query=String(item.query||''),results=(item.results||[]).slice(0,20),a=activity(tr('webSearch'),shortText(query),item.status,{icon:'⌕',kicker:tr('summary')});a.card.dataset.itemId=itemKey(item);a.body.append(el('div','activity-summary',query?`${tr('query')}: ${query}`:tr('available')));if(results.length)a.body.append(el('div','activity-facts',`${results.length} ${state.lang==='zh'?'条结果':'results'}`));for(const r of results){const row=el('div','search-result'),title=String(r?.title||r?.name||r?.url||'Result');if(typeof r?.url==='string'&&/^https?:\/\//.test(r.url)){const link=el('a','search-result-title',title);link.href=r.url;link.target='_blank';link.rel='noopener noreferrer';row.append(link)}else row.append(el('div','search-result-title',title));if(r?.snippet||r?.description||r?.text)row.append(el('div','muted',String(r.snippet||r.description||r.text)));a.body.append(row)}if(item.action)addTechnicalText(a.body,tr('viewRawData'),JSON.stringify(item.action,null,2));return a.card}
