function normalizeModels(r){return(r?.data||r?.models||[]).filter(x=>x&&!x.hidden)}
async function loadModels(){if(!hasRequest('model/list'))return;try{state.models=normalizeModels(await rpc('model/list',{}));renderModelControls()}catch(e){console.warn(e)}}
function currentModel(){return state.models.find(m=>(m.model||m.id)===$('modelSelect').value)}
function renderEfforts(){if(!$('effortSelect'))return;const prev=$('effortSelect').value,m=currentModel(),opts=[new Option(tr('defaultValue'),'')];for(const x of m?.supportedReasoningEfforts||[]){const v=x.reasoningEffort||x.effort||x;if(typeof v==='string')opts.push(new Option(v,v))}$('effortSelect').replaceChildren(...opts);const def=m?.defaultReasoningEffort||'';$('effortSelect').value=opts.some(o=>o.value===prev)?prev:(opts.some(o=>o.value===def)?def:'')}
function renderModelControls(){if(!$('modelSelect'))return;const prev=$('modelSelect').value,opts=[new Option(tr('defaultValue'),'')];for(const m of state.models)opts.push(new Option(m.displayName||m.model||m.id,m.model||m.id));$('modelSelect').replaceChildren(...opts);const def=state.models.find(m=>m.isDefault)?.model||'';$('modelSelect').value=opts.some(o=>o.value===prev)?prev:(opts.some(o=>o.value===def)?def:'');renderEfforts()}
function defaultFromSchema(s,root){if(!s)return{};if(s.default!==undefined)return s.default;if(s.const!==undefined)return s.const;if(s.enum?.length)return s.enum[0];if(s.$ref&&root?.definitions)return defaultFromSchema(root.definitions[s.$ref.split('/').pop()],root);if(s.oneOf?.length)return defaultFromSchema(s.oneOf[0],root);if(s.anyOf?.length)return defaultFromSchema(s.anyOf.find(x=>x.type!=='null')||s.anyOf[0],root);if(s.type==='array')return[];if(s.type==='boolean')return false;if(['integer','number'].includes(s.type))return 0;if(s.type==='string')return'';const o={};for(const k of s.required||[])o[k]=defaultFromSchema(s.properties?.[k],root);return o}
function methodBucket(){return state.methods?.[$('methodKind').value]||[]}
function methodKindLabel(kind){return({requests:state.lang==='zh'?'客户端请求':'Client request',notifications:state.lang==='zh'?'客户端通知':'Client notification',serverRequests:state.lang==='zh'?'服务端请求':'Server request',serverNotifications:state.lang==='zh'?'服务端通知':'Server notification'})[kind]||kind}
function capabilityMetric(method,result){if(method==='mcpServerStatus/list'){const count=Array.isArray(result?.data)?result.data.length:0;return{value:count,detail:state.lang==='zh'?`${count} 个服务已登记`:`${count} registered servers`}}if(method==='skills/list'){const count=(result?.data||[]).reduce((sum,entry)=>sum+(Array.isArray(entry?.skills)?entry.skills.length:0),0);return{value:count,detail:state.lang==='zh'?`${result?.data?.length||0} 个工作目录`:`${result?.data?.length||0} workspace(s)`}}if(method==='plugin/list'){const markets=Array.isArray(result?.marketplaces)?result.marketplaces.length:0,featured=Array.isArray(result?.featuredPluginIds)?result.featuredPluginIds.length:0;return{value:markets,detail:state.lang==='zh'?`${featured} 个精选插件`:`${featured} featured plugins`}}if(method==='app/installed'){const count=Array.isArray(result?.apps)?result.apps.length:0;return{value:count,detail:state.lang==='zh'?'官方 App 清单':'Official App inventory'}}return{value:0,detail:''}}
function renderCapabilities(cards){const root=$('capabilityCards');if(!root)return;root.replaceChildren(...cards.map(card=>{const node=el('div','capability-card');node.append(el('span','capability-card-label',card.label),el('strong','capability-card-value',String(card.value)));if(card.detail)node.append(el('small','capability-card-detail',card.detail));node.append(el('span',`capability-state ${card.ok?'ready':'unavailable'}`,card.ok?tr('capabilityReady'):tr('capabilityUnavailable')));return node}));$('capabilityStatus').textContent=state.meta?.schema?`${tr('capabilityTitle')} · ${state.meta.schema.clientRequests} ${state.lang==='zh'?'个官方请求':'official requests'}`:tr('capabilityTitle')}
