function renderMethods(){const q=$('methodSearch').value.trim().toLowerCase(),items=methodBucket().filter(x=>!q||x.method.toLowerCase().includes(q)||(x.description||'').toLowerCase().includes(q));if(!items.some(x=>x.method===state.selectedMethod?.method))state.selectedMethod=null;$('methodList').replaceChildren(...items.map(x=>{const info=readableMethodInfo(x),d=el('div','method-item'+(state.selectedMethod?.method===x.method?' active':'')+(x.allowed===false?' blocked':''));d.setAttribute('role','button');d.tabIndex=0;const top=el('div','method-item-top'),copy=el('div','method-item-copy');copy.append(el('strong','method-item-label',info.title),el('small','method-item-description',x.description||info.group));top.append(el('span','method-item-icon',info.group==='MCP server'||info.group==='MCP 服务'?'◈':'•'),copy);if(x.allowed===false)top.append(el('span','method-item-risk',tr('blocked')));d.append(top);const technical=el('details','method-technical');technical.append(el('summary','',tr('viewMethod')),el('code','',x.method));technical.addEventListener('click',e=>e.stopPropagation());d.append(technical);d.onclick=()=>selectMethod(x);d.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectMethod(x)}};return d}));if(!state.selectedMethod&&items[0])selectMethod(items[0])}
async function loadMethodSchema(item){if(!item||item.schema)return;const kind=$('methodKind').value;$('methodSchema').textContent='…';try{const r=await api(`/api/method-schema?kind=${encodeURIComponent(kind)}&method=${encodeURIComponent(item.method)}`);if(state.selectedMethod!==item)return;item.schema=r.schema;$('methodSchema').textContent=JSON.stringify(r.schema,null,2);$('methodParams').value=JSON.stringify(defaultFromSchema(r.schema,r.schema),null,2)}catch(e){if(state.selectedMethod===item)$('methodSchema').textContent=e.message}}
