function resizePrompt(){const p=$('prompt');p.style.height='auto';p.style.height=Math.min(p.scrollHeight,190)+'px'}
function nearBottom(){const t=$('timeline');return t.scrollHeight-t.scrollTop-t.clientHeight<100}
function scrollBottom(force=false){const t=$('timeline');if(force||nearBottom())requestAnimationFrame(()=>{t.scrollTop=t.scrollHeight;$('jumpBottom').classList.add('hidden')})}
function closeMobileSidebar(){$('sidebar').classList.remove('open');$('sidebarScrim').classList.add('hidden')}
function closeDrawer(){$('protocolPanel').classList.add('hidden');$('protocolPanel').setAttribute('aria-hidden','true')}
function openDrawer(){$('protocolPanel').classList.remove('hidden');$('protocolPanel').setAttribute('aria-hidden','false');loadCapabilitySummary()}
function clampDrawerWidth(width){return Math.max(320,Math.min(920,Math.min(window.innerWidth-24,width)))}
function setDrawerWidth(width){const value=clampDrawerWidth(width);$('protocolPanel').style.setProperty('--drawer-width',`${value}px`);localStorage.setItem('cweb_drawer_width',String(value));return value}
function setupDrawerResize(){const panel=$('protocolPanel'),handle=$('protocolResize');if(!panel||!handle)return;const saved=Number(localStorage.getItem('cweb_drawer_width'));if(Number.isFinite(saved)&&saved>0)setDrawerWidth(saved);let startX=0,startWidth=0,activePointer=null;const stop=()=>{document.body.classList.remove('drawer-resizing');if(activePointer!==null&&handle.hasPointerCapture?.(activePointer))handle.releasePointerCapture(activePointer);activePointer=null};handle.addEventListener('pointerdown',e=>{if(window.innerWidth<=760)return;activePointer=e.pointerId;startX=e.clientX;startWidth=panel.getBoundingClientRect().width;handle.setPointerCapture?.(e.pointerId);document.body.classList.add('drawer-resizing');e.preventDefault()});handle.addEventListener('pointermove',e=>{if(activePointer===null)return;setDrawerWidth(startWidth+startX-e.clientX)});handle.addEventListener('pointerup',stop);handle.addEventListener('pointercancel',stop);handle.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){setDrawerWidth(panel.getBoundingClientRect().width-32);e.preventDefault()}if(e.key==='ArrowRight'){setDrawerWidth(panel.getBoundingClientRect().width+32);e.preventDefault()}if(e.key==='Home'){setDrawerWidth(320);e.preventDefault()}if(e.key==='End'){setDrawerWidth(920);e.preventDefault()}})}
async function afterLogin(){$('loginModal').classList.add('hidden');$('loginModal').setAttribute('aria-hidden','true');[state.meta,state.methods]=await Promise.all([api('/api/meta'),api('/api/methods')]);$('workspaceHeader').textContent=state.meta.workspace;const s=state.meta.schema,p=state.meta.protocolSupport||protocolSupportSummary();$('schemaSummary').textContent=s.codexVersion+' · '+s.clientRequests+' requests · '+p.threadItemTypes+' Items · '+p.nativeServerRequests+' native · '+s.schemaDigest.slice(0,12);updateStatus();connectEvents();await Promise.all([refreshThreads(),loadModels()]);renderMethods()}
